// swift-tools-version: 6.2
// Fogar Desktop: the macOS companion app for fogar-agent (S1). `scripts/build-app.sh` wraps the
// FogarDesktop executable into a signed `.app`; `swift run fogar-standin` is a stand-in agent.
import PackageDescription

let package = Package(
    name: "FogarDesktop",
    platforms: [.macOS(.v14)],
    products: [
        .executable(name: "FogarDesktop", targets: ["FogarDesktop"]),
        .executable(name: "fogar-standin", targets: ["fogar-standin"]),
    ],
    targets: [
        // Wire types (generated by typeshare from crates/fogar-host/src), framing and the socket.
        // No default isolation: it is shared by the app and the stand-in.
        .target(name: "FogarWire"),
        .executableTarget(
            name: "FogarDesktop",
            dependencies: ["FogarWire"],
            exclude: ["Info.plist"],
            swiftSettings: [.defaultIsolation(MainActor.self)]
        ),
        // The stand-in agent's conversation rules (IPC v4), pure so they can be tested.
        .target(name: "FogarStandinKit", dependencies: ["FogarWire"]),
        .executableTarget(name: "fogar-standin", dependencies: ["FogarWire", "FogarStandinKit"]),
        .testTarget(name: "FogarWireTests", dependencies: ["FogarWire"]),
        .testTarget(name: "FogarStandinTests", dependencies: ["FogarStandinKit", "FogarWire"]),
        .testTarget(
            name: "FogarDesktopTests",
            dependencies: ["FogarDesktop"],
            swiftSettings: [.defaultIsolation(MainActor.self)]
        ),
    ]
)
